function drawEye(){
	strokeWeight(3);
	for(let i = 0; i < 20; i++){
		ellipse(0, 0, i* 20);
	}

	fill(0);
	ellipse(0, 0, 60);
}

function drawEyelids(){
	let res = 0.1;
	noFill();

	let close = (sin(millis()/1000)+1)/2;

	for(let y = 0; y < 40; y++){
		push();
		strokeWeight(S);
		translate(-100, y * S * X);
		beginShape();
		for(let x = -1; x < 1; x += (Math.max(0.001, Math.abs(res)) || 1)){
			let s = map(x, -1, 1, 0, 1);
			let e = E.easeOutSin(s);
			let h = sin(s*PI/2) * 100 * e * close;
			vertex(x * 100, h);
		}
		endShape();
		pop();
	}

	scale(-1,1);
	for(let y = 0; y < 40; y++){
		push();
		strokeWeight(S);
		translate(-100, y * S*X);
